package glitch

import data.glitch_lib

# Credential-related attribute name patterns
credential_patterns := {
    "password", "passwd", "pwd", "secret", "token", "key", "api_key", "access_key",
    "auth_token", "private_key", "certificate", "credential", "client_secret",
    "oauth_client_secret", "ssh_key", "master_password", "superuser_password",
    "bootstrap_password", "initial_password", "setup_password", "default_user",
    "admin_user", "root_user", "registry_credentials", "repository_credentials",
    "service_account_key", "connection_string", "dsn", "uri", "url", "connection_uri"
}

# Common hardcoded default values
default_passwords := {
    "admin", "password", "123456", "default", "changeme", "pass", "admin123",
    "root", "toor", "guest", "user", "login", "welcome", "master", "nginx",
    "apache", "mysql", "postgres", "oracle", "mongo", "redis", "test", "test123",
    "temp", "temporary", "example", "demo", "secret", "secret123", "key", "token"
}

# Connection string password indicators
connection_indicators := ["pass=", "pwd=", "password=", ":", "@"]

# Check if attribute name suggests credential storage
is_credential_attribute(name) {
    lower_name := lower(name)
    pattern := credential_patterns[_]
    contains(lower_name, pattern)
} else {
    lower_name := lower(name)
    endswith(lower_name, "_password")
} else {
    lower_name := lower(name)
    endswith(lower_name, "_secret")
} else {
    lower_name := lower(name)
    endswith(lower_name, "_key")
} else {
    lower_name := lower(name)
    endswith(lower_name, "_token")
}

# Check if value appears to be hardcoded credential (not a reference)
is_hardcoded_credential(value) {
    value.ir_type == "String"
    value.value != ""
    not starts_with(value.value, "${")
    not starts_with(value.value, "{{")
    not starts_with(value.value, "var.")
    not starts_with(value.value, "module.")
    not starts_with(value.value, "data.")
    not starts_with(value.value, "$env")
    not starts_with(value.value, "$ENV")
}

# Check for common default passwords
is_common_default(value) {
    lower_val := lower(value.value)
    default_passwords[lower_val]
}

# Check for base64 encoded pattern
is_base64_like(value) {
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", value.value)
}

# Check for hex/API key pattern
is_api_key_like(value) {
    regex.match("^[a-f0-9]{32,}$|^[A-F0-9]{32,}$", value.value)
}

# Check for UUID-like pattern
is_uuid_like(value) {
    regex.match("^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$", lower(value.value))
}

# Check connection string for embedded credentials
has_embedded_credential(value) {
    indicator := connection_indicators[_]
    contains(value.value, indicator)
}

# Check if password authentication is enabled with literal password
has_insecure_password_authentication(attrs) {
    some i, j
    attrs[i].name == "password_authentication"
    attrs[i].value.ir_type == "Boolean"
    attrs[i].value.value == true
    attrs[j].name == "password"
    is_hardcoded_credential(attrs[j].value)
}

# Check individual attribute for hardcoded credential
check_hardcoded_credential(attr) {
    is_credential_attribute(attr.name)
    is_hardcoded_credential(attr.value)
    is_common_default(attr.value)
}

check_hardcoded_credential(attr) {
    is_credential_attribute(attr.name)
    is_hardcoded_credential(attr.value)
    is_base64_like(attr.value)
}

check_hardcoded_credential(attr) {
    is_credential_attribute(attr.name)
    is_hardcoded_credential(attr.value)
    is_api_key_like(attr.value)
}

check_hardcoded_credential(attr) {
    is_credential_attribute(attr.name)
    is_hardcoded_credential(attr.value)
    is_uuid_like(attr.value)
}

check_hardcoded_credential(attr) {
    lower_name := lower(attr.name)
    contains(lower_name, "connection")
    is_hardcoded_credential(attr.value)
    has_embedded_credential(attr.value)
}

# Recursively check for credentials in complex values
find_credential_in_value(name, value, result) {
    is_credential_attribute(name)
    is_hardcoded_credential(value)
    result := value
}

find_credential_in_value(name, value, result) {
    value.ir_type == "Hash"
    pair := value.value[_]
    find_credential_in_value(pair.key.value, pair.value, result)
}

find_credential_in_value(name, value, result) {
    value.ir_type == "Array"
    elem := value.value[_]
    find_credential_in_value(name, elem, result)
}

# Main rule: check attributes directly
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    check_hardcoded_credential(attr)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be hard-coded in configuration files. (CWE-798)"
    }
}

# Check for insecure password authentication combination
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    has_insecure_password_authentication(attrs)

    attr := [a | a := attrs[_]; a.name == "password"][_]

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be hard-coded in configuration files. (CWE-798)"
    }
}

# Check variables for hardcoded credentials
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var := variables[_]
    check_hardcoded_credential(var)

    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be hard-coded in configuration files. (CWE-798)"
    }
}

# Check nested credential structures in Hash values
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.value.ir_type == "Hash"

    credential_attr := attr.value.value[k]
    is_credential_attribute(k.value)
    is_hardcoded_credential(credential_attr)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be hard-coded in configuration files. (CWE-798)"
    }
}

