credential_keywords := {"password", "passwd", "pwd", "secret", "token", "api_key", "access_key", "auth_token", "private_key", "certificate", "credential", "client_secret", "oauth_client_secret", "ssh_key", "master_password", "superuser_password", "bootstrap_password", "initial_password", "setup_password", "registry_credentials", "repository_credentials", "service_account_key", "sha512_password", "sha256_password", "sha_password", "hashed_password", "encrypted_password", "pass"}

credential_suffixes := {"_password", "_secret", "_key", "_token", "_pwd"}

default_passwords := {"password", "123456", "default", "changeme", "admin", "admin123", "root", "toor", "guest", "user", "login", "welcome", "master", "test", "test123", "temp", "temporary", "example", "demo", "secret123", "password123", "administrator", "qwerty", "letmein", "sensu", "telarista"}

is_credential_name(name) {
    lower_name := lower(name)
    kw := credential_keywords[_]
    lower_name == kw
}

is_credential_name(name) {
    lower_name := lower(name)
    suffix := credential_suffixes[_]
    endswith(lower_name, suffix)
}

is_default_password(val) {
    lower_val := lower(val)
    dp := default_passwords[_]
    lower_val == dp
}

is_base64_val(val) {
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", val)
}

is_hash_val(val) {
    regex.match("^\\$[0-9a-z]+\\$", val)
}

looks_like_secret(val) {
    is_default_password(val)
}

looks_like_secret(val) {
    is_base64_val(val)
}

looks_like_secret(val) {
    is_hash_val(val)
}

is_suspicious_credential_value(key_name, val) {
    is_credential_name(key_name)
    looks_like_secret(val)
}

is_suspicious_credential_value(key_name, val) {
    is_credential_name(key_name)
    count(val) >= 8
    not val == "true"
    not val == "false"
    not regex.match("^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$", val)
}

find_credential_in_value(node, key_name, path, parent_elem) = result {
    node.ir_type == "String"
    node.value != ""
    is_suspicious_credential_value(key_name, node.value)
    result := {
        "type": "sec_hard_secr",
        "element": parent_elem,
        "path": path,
        "description": "Use of hard-coded credentials - Credentials should not be hard-coded in configuration files. (CWE-798)"
    }
}

find_credential_in_hash_entries(entries, path, parent_elem) = result {
    entry := entries[_]
    entry.key.ir_type == "String"
    key_name := entry.key.value

    result := find_credential_in_value(entry.value, key_name, path, parent_elem)
}

find_credential_in_hash_entries(entries, path, parent_elem) = result {
    entry := entries[_]
    entry.key.ir_type == "String"
    entry.value.ir_type == "Hash"
    inner_entries := entry.value.value

    result := find_credential_in_hash_entries(inner_entries, path, parent_elem)
}

walk_credential_search(node, path, parent_elem) = result {
    node.ir_type == "Hash"
    entries := node.value
    result := find_credential_in_hash_entries(entries, path, parent_elem)
}

walk_credential_search(node, path, parent_elem) = result {
    node.ir_type == "Array"
    item := node.value[_]
    result := walk_credential_search(item, path, parent_elem)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := parent.variables
    var := vars[_]

    result := walk_credential_search(var.value, parent.path, var)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    result := find_credential_in_value(attr.value, attr.name, parent.path, attr)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]
    attr.value.ir_type == "Hash"

    result := walk_credential_search(attr.value, parent.path, attr)
}

